import { test } from 'node:test';
import assert from 'node:assert/strict';
import { artifact } from '../evm.mjs';

// The complete external state-changing surface. docs/AUDIT-PACKET.md lists the same set (generated by print-abi.mjs).
const EXPECTED_WRITE = {
  approve: 'token owner or approved operator',
  setApprovalForAll: 'any holder (own approvals only)',
  transferFrom: 'token owner or approved',
  safeTransferFrom: 'token owner or approved',
  mint: 'anyone (payable, exact price, ladder rules)',
  commitClaim: 'anyone (stores a commitment for itself)',
  revealClaim: 'a wallet with an aged matching commitment',
  withdraw: 'anyone (sends the balance to immutable TREASURY only)',
};

test('no admin surface: state-changing functions are exactly the expected set', () => {
  for (const name of ['GridlockCars', 'GridlockRenderer']) {
    const abi = artifact(name).abi;
    const writes = [...new Set(abi.filter((x) => x.type === 'function' && !['view', 'pure'].includes(x.stateMutability)).map((x) => x.name))].sort();
    if (name === 'GridlockRenderer') assert.deepEqual(writes, []);
    else assert.deepEqual(writes, Object.keys(EXPECTED_WRITE).sort());
  }
});

test('no owner, upgrade, pause, burn, setter or arbitrary-withdraw names exist anywhere in the ABI', () => {
  const bad = /^(owner$|transferOwnership|renounceOwnership|upgrade|upgradeTo|pause|unpause|burn|set[A-Z]|init|initialize|rescue|sweep|emergency|grantRole|revokeRole|multicall|execute|call|delegate)/;
  for (const name of ['GridlockCars', 'GridlockRenderer']) {
    for (const f of artifact(name).abi.filter((x) => x.type === "function" && x.name !== "setApprovalForAll")) assert.ok(!bad.test(f.name), `suspicious function ${f.name}`);
  }
  const cars = artifact('GridlockCars').abi;
  assert.ok(!cars.some((x) => x.type === 'receive' || x.type === 'fallback'), 'no receive or fallback');
});

test('the renderer bytecode contains no SELFDESTRUCT or DELEGATECALL, and neither does the cars contract', () => {
  // Opcode scan that skips PUSH data.
  const scan = (hex) => {
    const b = Buffer.from(hex.slice(2), 'hex');
    const found = new Set();
    for (let i = 0; i < b.length; i++) {
      const op = b[i];
      if (op >= 0x60 && op <= 0x7f) { i += op - 0x5f; continue; }
      if (op === 0xff) found.add('SELFDESTRUCT');
      if (op === 0xf4) found.add('DELEGATECALL');
      if (op === 0xf2) found.add('CALLCODE');
    }
    return [...found];
  };
  assert.deepEqual(scan(artifact('GridlockRenderer').deployedBytecode), []);
  assert.deepEqual(scan(artifact('GridlockCars').deployedBytecode), []);
});
